import http from 'k6/http';
import { check, sleep } from 'k6';
import { Counter, Rate, Trend } from 'k6/metrics';
import * as shard from './lib/shard.js';

// Load environment configuration generated by setup.ts
const env = JSON.parse(open('./k6-env.json'));

const readOps = new Counter('mixed_read_ops');
const writeOps = new Counter('mixed_write_ops');
const poolExhaustionErrors = new Rate('pool_exhaustion_errors');
const mixedDuration = new Trend('mixed_req_duration_ms');

// Configurable duration: default 30s for quick test, pass -e DURATION=10m for full 10-minute rubric run
const testDuration = __ENV.DURATION || '30s';

// #251 distributed run — same reasoning as 01-read-products.js: nginx's per-IP limiter caps
// request rate, not VU count, so a shard runs its own safe fixed rate (r/s) rather than a
// fraction of "500 VUs". See README.md "Per-shard math". With no SHARD set, unchanged.
const shardInfo = shard.shardFromEnv(__ENV);
const ratePerSecond = Number(__ENV.RATE_PER_SHARD || shard.SAFE_RATE_PER_SHARD);
if (shardInfo) shard.assertRateSafe(ratePerSecond, 'k6:mixed (04-mixed-workload)');

export const options = {
  scenarios: {
    mixed_workload: shardInfo
      ? {
          executor: 'ramping-arrival-rate',
          startRate: 0,
          timeUnit: '1s',
          preAllocatedVUs: 60,
          maxVUs: 150,
          stages: [
            { duration: '5s', target: Math.round(ratePerSecond * 0.5) },
            { duration: testDuration, target: ratePerSecond },
            { duration: '5s', target: 0 },
          ],
        }
      : {
          executor: 'ramping-vus',
          startVUs: 0,
          stages: [
            { duration: '5s', target: 250 },
            { duration: testDuration, target: 500 },
            { duration: '5s', target: 0 },
          ],
          gracefulRampDown: '3s',
        },
  },
  thresholds: {
    // Rubric requirement: error < 0.1%, p95 < 500ms, no pool exhaustion
    http_req_failed: ['rate<0.001'],
    http_req_duration: ['p(95)<500'],
    pool_exhaustion_errors: ['rate==0'],
  },
};

function generateUUID() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

export default function () {
  // 80% read / 20% write distribution
  const isRead = Math.random() < 0.8;

  if (isRead) {
    const page = (__ITER % 5) + 1;
    const url = `${env.baseUrl}/api/v1/products?page=${page}&limit=10`;
    const res = http.get(url, {
      headers: {
        Authorization: `Bearer ${env.boToken}`,
        Accept: 'application/json',
      },
      tags: { name: 'MixedRead' },
    });

    mixedDuration.add(res.timings.duration);
    readOps.add(1);

    const isExhausted = res.status === 500 || res.status === 503;
    poolExhaustionErrors.add(isExhausted);

    check(res, {
      'read status is 200': (r) => r.status === 200,
    });
  } else {
    const url = `${env.baseUrl}/api/v1/sales`;
    const saleId = `sale-mixed-${generateUUID()}`;
    const idemKey = `idem-mixed-${__VU}-${__ITER}-${Date.now()}`;

    // Select product from catalogue (p_1 to p_50)
    const productIdx = ((__VU + __ITER) % 50) + 1;
    const prodId = env.products && env.products[productIdx] ? env.products[productIdx] : `p_${productIdx}`;

    const payload = JSON.stringify({
      id: saleId,
      subtotal: 100.0,
      discount: 0.0,
      total: 100.0,
      paymentMethod: 'เงินสด',
      items: [
        {
          productId: prodId,
          name: `Catalogue Part ${productIdx}`,
          qty: 1,
          price: 100.0,
        },
      ],
    });

    const res = http.post(url, payload, {
      headers: {
        Authorization: `Bearer ${env.posToken}`,
        'Idempotency-Key': idemKey,
        'Content-Type': 'application/json',
        Accept: 'application/json',
      },
      tags: { name: 'MixedWrite' },
    });

    mixedDuration.add(res.timings.duration);
    writeOps.add(1);

    const isExhausted = res.status === 500 || res.status === 503;
    poolExhaustionErrors.add(isExhausted);

    check(res, {
      'write status is 201': (r) => r.status === 201,
    });
  }

  sleep(0.35);
}
